//! Physical slots in a partially materialized coverage plan. Packet addresses are the
//! immutable logical slots assigned during collection, even if a span migrates in CPU memory.
use super::*;
use crate::frame::NodeSpan;
use crate::seams::{BodyPaint, DrawItem};
use std::hash::{Hash, Hasher};

pub(crate) const ABSENT: usize = usize::MAX;
/// The span's output is regenerated by its enclosing execution unit.
const IN_UNIT: usize = usize::MAX - 1;

/// The retained unit needs its display-list membership, ordinal and role. All values
/// of a paint item (including its clip and world transform) come from the scene.
#[derive(Default)]
pub(super) struct Sources {
    rows: Vec<u32>,
    // Between breaks the display-list ordinal advances by one per item.
    ordinals: Vec<(usize, usize)>,
    generated: HashMap<usize, Box<str>>,
    secondary: HashMap<usize, moda_scene::types::PaintKind>,
}

impl Sources {
    pub(super) fn push(&mut self, scene: &Scene, items: &[moda_scene::types::PaintItem]) -> std::ops::Range<usize> {
        let start = self.rows.len();
        self.rows.reserve(items.len());
        for p in items {
            let i = self.rows.len();
            if self.ordinals.last().is_none_or(|&(at, z)| z.checked_add(i - at) != Some(p.z_index)) {
                self.ordinals.push((i, p.z_index));
            }
            self.rows.push(scene.row_of(&p.node_id).unwrap_or_else(|| {
                self.generated.insert(i, p.node_id.as_str().into());
                u32::MAX
            }));
            if !p.is_primary_node_item { self.secondary.insert(i, p.kind); }
        }
        start..self.rows.len()
    }

    pub(super) fn bytes(&self) -> usize {
        weights::capacity(&self.rows) + weights::capacity(&self.ordinals)
            + self.generated.capacity() * std::mem::size_of::<(usize, Box<str>)>()
            + self.generated.values().map(|id| id.len()).sum::<usize>()
            + self.secondary.capacity() * std::mem::size_of::<(usize, moda_scene::types::PaintKind)>()
    }

    fn id<'a>(&'a self, scene: &'a Scene, i: usize) -> &'a str {
        let row = self.rows[i];
        if row == u32::MAX { &self.generated[&i] } else { scene.row(row).expect("retained source row").id() }
    }

    pub(super) fn names<'a>(&'a self, seg: &'a crate::frame::CameraSegment, scene: &'a Scene,
        unit: &crate::frame::PlanUnit) -> impl Iterator<Item = &'a str> {
        (unit.dl_start..unit.dl_end).map(move |i| if self.rows.is_empty() {
            seg.dl.items[i].node_id.as_str()
        } else { self.id(scene, i) })
    }

    pub(super) fn load<'a>(&self, dl: &'a moda_scene::DisplayList, scene: &Scene, unit: &crate::frame::PlanUnit,
        masks: &weights::RetainedSet<String>) -> Option<std::borrow::Cow<'a, [moda_scene::types::PaintItem]>> {
        let range = unit.dl_start..unit.dl_end;
        if self.rows.is_empty() { return Some(std::borrow::Cow::Borrowed(dl.items.get(range)?)); }
        self.rows.get(range.clone())?;
        let source = |i| {
            let &(at, z) = &self.ordinals[self.ordinals.partition_point(|&(at, _)| at <= i) - 1];
            (z + (i - at), self.id(scene, i))
        };
        let mut prev = None;
        let nodes = range.clone().map(source).filter(|&node| {
            let include = prev != Some(node);
            prev = Some(node);
            include
        });
        let mut emitted = moda_scene::display_list::display_list_items_at(scene, nodes, masks).into_iter();
        let mut result = Vec::with_capacity(range.len());
        for i in range {
            let (z, id) = source(i);
            let kind = self.secondary.get(&i);
            result.push(emitted.find(|p| p.z_index == z && p.node_id == id &&
                if let Some(kind) = kind { !p.is_primary_node_item && p.kind == *kind } else { p.is_primary_node_item })?);
        }
        Some(std::borrow::Cow::Owned(result))
    }
}

// The executor needs the source interval, its starting depth and its fixed output extent.
// Frame construction uses wider coordinates. A range we cannot encode stays resident.
#[derive(Clone, Copy)]
struct ColdUnit {
    index: u32,
    logical: u32,
    len: u32,
    end_row: u32,
    dl_start: u32,
    dl_end: u32,
    z: u32,
    depth: u32,
}

impl ColdUnit {
    fn new(index: usize, logical: usize, unit: &crate::frame::PlanUnit, end_row: Option<u32>) -> Option<Self> {
        Some(Self { index: index.try_into().ok()?, logical: logical.try_into().ok()?,
            len: unit.item_len.try_into().ok()?, end_row: end_row.unwrap_or(u32::MAX),
            dl_start: unit.dl_start.try_into().ok()?, dl_end: unit.dl_end.try_into().ok()?,
            z: unit.z.try_into().ok()?, depth: unit.z_consumed.try_into().ok()? })
    }

    fn source(&self) -> crate::frame::PlanUnit {
        crate::frame::PlanUnit { dl_start: self.dl_start as usize, dl_end: self.dl_end as usize,
            item_start: ABSENT, item_len: self.len as usize, z: self.z.into(), z_consumed: self.depth.into(), ..Default::default() }
    }
}

// A patch that restores a unit to the working set also restores its flat span addresses
// and checks the immutable draw state. A CPU snapshot only needs the ColdUnit.
struct SpanMembers {
    draw: Option<u64>,
    members: Vec<u32>,
}

#[derive(Default)]
struct ColdUnits {
    ranges: Vec<ColdUnit>,
    spans: std::collections::BTreeMap<usize, SpanMembers>,
}

impl ColdUnits {
    fn bytes(&self) -> usize {
        weights::capacity(&self.ranges) + self.spans.values().map(|m|
            std::mem::size_of::<SpanMembers>() + 32 + weights::capacity(&m.members)).sum::<usize>()
    }

    fn position(&self, ui: usize) -> Option<usize> {
        let key = u32::try_from(ui).ok()?;
        if self.ranges.get(ui).is_some_and(|r| r.index == key) { return Some(ui); }
        self.ranges.binary_search_by_key(&key, |r| r.index).ok()
    }

    fn get(&self, ui: usize) -> Option<&ColdUnit> {
        self.ranges.get(self.position(ui)?).filter(|r| r.len != 0)
    }

    fn add(&mut self, ranges: Vec<(ColdUnit, SpanMembers)>) {
        self.ranges.retain(|r| r.len != 0);
        self.ranges.reserve_exact(ranges.len());
        for (range, spans) in ranges {
            self.spans.insert(range.index as usize, spans);
            self.ranges.push(range);
        }
        self.ranges.sort_unstable_by_key(|r| r.index);
    }
}

#[derive(Clone)]
pub struct ItemAddresses {
    pub(crate) total: usize,
    pub(crate) slots: Vec<u32>,
    sorted: usize,
    suffix: HashMap<u32, u32>,
}
impl ItemAddresses {
    pub(super) fn complete(&self) -> bool { self.sorted == self.total && self.slots.len() == self.total }

    fn append(&mut self, start: u32, count: u32) -> Option<()> {
        let end = start.checked_add(count)?;
        let ordered = self.sorted == self.slots.len() && self.slots.last().is_none_or(|&last| last < start);
        if !ordered {
            let physical = u32::try_from(self.slots.len()).ok()?;
            physical.checked_add(count)?;
            self.suffix.extend((start..end).zip(physical..));
        }
        self.slots.extend(start..end);
        if ordered { self.sorted = self.slots.len(); }
        Some(())
    }

    pub(crate) fn physical(&self, logical: usize) -> Option<usize> {
        let key = u32::try_from(logical).ok()?;
        self.slots[..self.sorted].binary_search(&key).ok()
            .or_else(|| self.suffix.get(&key).map(|&at| at as usize))
    }
    pub fn logical(&self, physical: usize) -> Option<usize> {
        self.slots.get(physical).map(|&slot| slot as usize)
    }
}

#[derive(Clone, Copy)]
struct SpanAddress {
    logical: u32,
    len: u32,
    draw: u64,
}

pub(super) struct PlanParts {
    identities: DrawIdentities,
    spans: Vec<SpanAddress>,
    units: ColdUnits,
    pub(super) addresses: Arc<ItemAddresses>,
}

/// Weak keys keep addresses unique across restorations without retaining the resource itself.
#[derive(Default)]
struct DrawIdentities {
    geometry: HashMap<usize, (std::sync::Weak<TessellatedGeometry>, u64)>,
    pixels: HashMap<usize, (std::sync::Weak<Vec<u8>>, u64)>,
}

impl DrawIdentities {
    fn bytes(&self) -> usize {
        (self.geometry.capacity() + self.pixels.capacity()) * std::mem::size_of::<(usize, (usize, u64))>()
    }

    fn hash<T>(cache: &mut HashMap<usize, (std::sync::Weak<T>, u64)>, value: &Arc<T>, hash: impl FnOnce(&T, &mut FxHasher)) -> u64 {
        let at = Arc::as_ptr(value) as usize;
        if let Some((_, key)) = cache.get(&at) { return *key; }
        let mut h = FxHasher::default();
        hash(value, &mut h);
        let key = h.finish();
        if Arc::strong_count(value) > 1 { cache.insert(at, (Arc::downgrade(value), key)); }
        key
    }
}

// A discarded item need not be reconstructed at its *old* transform or paint. Preserve the
// draw state outside the writable record. The ordinary emitter supplies the current record.
fn draw_key(cache: &mut DrawIdentities, items: &[DrawItem]) -> Option<u64> {
    let mut h = FxHasher::default();
    items.len().hash(&mut h);
    for item in items {
        std::mem::discriminant(item).hash(&mut h);
        drawitem_node_id(item).hash(&mut h);
        match item {
            DrawItem::Body { phase, paint, geometry, blend_mode, mask, z, .. } => {
                (*phase as u8, *blend_mode as u8, z.to_bits(), mask.as_ref().map(|m| m.mask_id)).hash(&mut h);
                std::mem::discriminant(paint).hash(&mut h);
                if let BodyPaint::Pattern(p) = paint {
                    (p.texture_slot, &p.texture.key, p.texture.state as u8, p.clamp_sampler).hash(&mut h);
                    let img = &p.texture.image;
                    (img.width, img.height, img.straight).hash(&mut h);
                    if let Some(ext) = &img.external {
                        (&ext.key, ext.upload_id).hash(&mut h);
                    } else {
                        DrawIdentities::hash(&mut cache.pixels, &img.rgba_premultiplied, |bytes, h| bytes.hash(h)).hash(&mut h);
                    }
                }
                DrawIdentities::hash(&mut cache.geometry, geometry, |geometry, h| {
                    geometry.vertex_count.hash(h);
                    for values in [&geometry.positions, &geometry.vertex_types, &geometry.stroke_uv] {
                        bytemuck::cast_slice::<f32, u8>(values).hash(h);
                    }
                }).hash(&mut h);
            }
            DrawItem::BackdropSplit(s) if matches!(s.op, crate::seams::BackdropOp::BlendBegin |
                crate::seams::BackdropOp::StackEnd { mode: 0, .. }) => {
                // Both endpoints are re-encoded from the new plan. The packet's
                // draw records between them stay usable across a changed scissor.
                std::mem::discriminant(&s.op).hash(&mut h);
            }
            DrawItem::Text(batch) => batch.z.to_bits().hash(&mut h),
            DrawItem::Shadow { z, inner, .. } => (z.to_bits(), inner).hash(&mut h),
            DrawItem::SolidShapeSdf { z, phase, opaque_sdf_covers_shadow, .. }
            | DrawItem::GradientShapeSdf { z, phase, opaque_sdf_covers_shadow, .. } =>
                (z.to_bits(), *phase as u8, opaque_sdf_covers_shadow).hash(&mut h),
            DrawItem::PageFill { .. } => {}
            _ => return None,
        }
    }
    Some(h.finish())
}

impl PlanParts {
    pub(super) fn bytes(&self) -> usize {
        weights::capacity(&self.spans) + weights::capacity(&self.addresses.slots)
            + self.addresses.suffix.capacity() * std::mem::size_of::<(u32, u32)>() + self.identities.bytes()
            + self.units.bytes()
    }

    /// Release the flat span index when the execution ranges alone exceed the allowance.
    /// Every missing slot must belong to a replayable unit. Keep the prefix and any
    /// output outside those units verbatim (including the page fill).
    pub(super) fn from_units(scene: &Scene, plan: &CoveragePlan, segment: &crate::frame::CameraSegment,
        sources: &Sources, prior: Option<&Self>) -> Option<(Self, CoveragePlan, SourceLookup)> {
        if !plan.masks.is_empty() || plan.item_order.is_some() || segment.layer_blur
            || segment.mask_scope.clip_bindings().next().is_some() { return None; }
        let total = prior.map_or(plan.items.len(), |p| p.addresses.total);
        u32::try_from(total).ok()?;
        let logical = |physical| prior.map_or(Some(physical), |p| p.addresses.logical(physical));
        let mut ranges = Vec::new();
        let mut owners = SourceLookup::default();
        let mut keep = vec![true; plan.items.len()];
        for (ui, unit) in segment.units.iter().enumerate() {
            if unit.item_len == 0 { continue; }
            if unit.culled || unit.part_culled || unit.details.is_some() { return None; }
            let (start, end_row) = if unit.item_start == ABSENT {
                let cold = prior?.units.get(ui)?;
                (cold.logical as usize, Some(cold.end_row).filter(|&r| r != u32::MAX))
            } else {
                let at = segment.prefix.checked_add(unit.item_start)?;
                let end = at.checked_add(unit.item_len)?;
                let items = plan.items.get(at..end)?;
                let start = logical(at)?;
                if logical(end - 1)? != start + unit.item_len - 1 { return None; }
                keep.get_mut(at..end)?.fill(false);
                (start, Self::end_row(scene, unit, items))
            };
            let range = ColdUnit::new(ui, start, unit, end_row)?;
            if let Some(row) = end_row {
                let node = scene.row(row)?;
                if scene.placeable(row) && sources.names(segment, scene, unit).next() == Some(node.id()) {
                    if owners.row(row).is_some() { return None; }
                    owners.insert(scene, node.id(), ui);
                }
            }
            ranges.push(range);
        }
        if ranges.is_empty() { return None; }
        let mut items = Vec::new();
        let mut slots = Vec::new();
        for (at, keep) in keep.into_iter().enumerate() {
            if keep { slots.push(u32::try_from(logical(at)?).ok()?); items.push(plan.items[at].clone()); }
        }
        // Each physical item was either kept or had exactly one owner. A previously
        // discarded ordinary span cannot be recovered after releasing its source.
        if ranges.iter().map(|r| r.len as usize).sum::<usize>() + slots.len() != total || !slots.is_sorted() { return None; }
        ranges.shrink_to_fit();
        let sorted = slots.len();
        let parts = Self { identities: Default::default(), spans: Vec::new(),
            units: ColdUnits { ranges, spans: Default::default() },
            addresses: Arc::new(ItemAddresses { total, slots, sorted, suffix: Default::default() }) };
        Some((parts, plan.with_items(items), owners))
    }

    fn end_row(scene: &Scene, unit: &crate::frame::PlanUnit, items: &[DrawItem]) -> Option<u32> {
        let row = unit.opacity_row()?;
        let DrawItem::BackdropSplit(split) = items.last()? else { return None; };
        (matches!(split.op, crate::seams::BackdropOp::StackEnd { .. }) && scene.row(row)?.id() == split.node_id).then_some(row)
    }

    pub(super) fn compact(
        scene: &Scene, warnings: &PlanWarnings, plan: &CoveragePlan, patch: &mut Patchable, publications: Option<&PublicationIndex>, remaining: usize,
    ) -> Option<(Self, CoveragePlan, usize)> {
        if u32::try_from(plan.items.len()).is_err() { return None; }
        let spans = (0..patch.index.spans.len()).map(|si| {
            let (start, len) = patch.index.spans.range(si);
            SpanAddress { logical: start as u32, len: len as u32, draw: 0 }
        }).collect();
        let mut parts = Self { identities: Default::default(), spans, units: Default::default(), addresses: Arc::new(ItemAddresses { total: plan.items.len(), slots: Vec::new(), sorted: 0, suffix: HashMap::default() }) };
        let (compact, bytes) = parts.fit(scene, warnings, patch, plan, publications, remaining, &[], true)?;
        Some((parts, compact, bytes))
    }

    /// Trim the current materialization, preserving logical slot identities. Prefer spans
    /// touched by this revision. The current frame may still own the previous (larger) view.
    pub(super) fn fit(&mut self, scene: &Scene, warnings: &PlanWarnings, patch: &mut Patchable, plan: &CoveragePlan, publications: Option<&PublicationIndex>, budget: usize,
        touched: &[u32], first: bool) -> Option<(CoveragePlan, usize)> {
        let index = &mut patch.index;
        // Unit item ranges execute and replace as a whole. Keep their contiguous output slots
        // while their independent ordinary source and packet data can be trimmed around them.
        let seg = patch.units.as_mut().and_then(|u| u.segment.as_mut());
        let mut pinned = vec![false; plan.items.len()];
        if let Some(seg) = seg.as_deref() {
            for unit in &seg.units {
                if unit.item_start == ABSENT { continue; }
                let at = seg.prefix + unit.item_start;
                pinned.get_mut(at..at.checked_add(unit.item_len)?)?.fill(true);
            }
        }
        let mut allocations = weights::Allocations::default();
        // Fixed masks can share allocations with an item being considered for eviction.
        if let Some(index) = publications { index.mask_read_bytes(&mut allocations); }
        allocations.masks(&plan.masks);
        let mut bytes = self.units.bytes()
            + weights::capacity(&self.spans) + allocations.items(&plan.items) + 4 * plan.items.len();
        let previous_overhead = self.identities.bytes() + self.addresses.suffix.capacity() * std::mem::size_of::<(u32, u32)>();
        bytes += previous_overhead;
        allocations.removing = true;
        let mut evict = vec![false; plan.items.len()];
        let mut absent = vec![false; index.spans.len()];
        let recent = |start: usize, len: usize| {
            let at = touched.partition_point(|&i| (i as usize) < start);
            touched.get(at).is_some_and(|&i| (i as usize) < start + len)
        };
        for active in [false, true] {
            if bytes <= budget { break; }
            for si in (0..index.spans.len()).rev() {
                let (start, len) = index.spans.range(si);
                if bytes <= budget && (si + 1) % 256 == 0 { break; }
                if start >= IN_UNIT || len == 0 || recent(start, len) != active { continue; }
                let range = start..start.checked_add(len)?;
                let Some(slice) = plan.items.get(range.clone()) else { continue; };
                if pinned[range.clone()].contains(&true) || evict[range.clone()].contains(&true) { continue; }
                if !patch.rows.as_ref().is_some_and(|rows| rows.follows[si]) {
                    let id = index.spans[si].source.id(scene);
                    if slice.iter().any(|item| drawitem_node_id(item) != Some(id))
                        || warnings_mention_node(&warnings.skipped, id) || warnings_mention_node(&warnings.dropped, id) { continue; }
                }
                let Some(key) = draw_key(&mut self.identities, slice) else { continue; };
                evict[range.clone()].fill(true);
                bytes -= allocations.items(slice) + slice.len() * 4;
                absent[si] = true;
                self.spans[si].draw = key;
            }
        }
        // A unit is the planner's own indivisible execution range. Its ordinary executor
        // restores masked, filtered or grouped output when the last CPU copy is evicted.
        let mut cold_owner = Vec::new();
        let mut cold_units = Vec::new();
        if bytes > budget {
            if let Some(seg) = seg.as_deref() {
                // A restored compact range has no full header. Its immutable logical
                // interval still identifies the contiguous physical output we appended.
                if seg.units.is_empty() {
                    for range in &self.units.ranges {
                        if bytes <= budget { break; }
                        let Some(at) = self.addresses.physical(range.logical as usize) else { continue; };
                        let end = at.checked_add(range.len as usize)?;
                        let items = plan.items.get(at..end)?;
                        bytes -= allocations.items(items) + 4 * items.len();
                        evict[at..end].fill(true);
                    }
                }
                cold_owner.resize(plan.items.len(), usize::MAX);
                // Charge every member address before selecting the unit for eviction.
                let mut member_prefix = vec![0u32; plan.items.len() + 1];
                for si in 0..index.spans.len() {
                    let (start, len) = index.spans.range(si);
                    if len != 0 && start < plan.items.len() { member_prefix[start + 1] += 1; }
                }
                for i in 1..member_prefix.len() { member_prefix[i] += member_prefix[i - 1]; }
                let free_ranges = self.units.ranges.capacity() - self.units.ranges.iter().filter(|r| r.len != 0).count();
                for active in [false, true] {
                    for (ui, unit) in seg.units.iter().enumerate().rev() {
                        if bytes <= budget { break; }
                        if unit.item_start == ABSENT || unit.item_len == 0 { continue; }
                        let at = seg.prefix + unit.item_start;
                        let range = at..at.checked_add(unit.item_len)?;
                        if evict[range.clone()].contains(&true) { continue; }
                        let ti = touched.partition_point(|&t| (t as usize) < at);
                        if touched.get(ti).is_some_and(|&t| (t as usize) < range.end) != active { continue; }
                        let logical = if first { at as u32 } else { self.addresses.slots[at] };
                        let items = plan.items.get(range.clone())?;
                        let saved = allocations.items(items) + 4 * items.len();
                        let members = Vec::with_capacity((member_prefix[range.end] - member_prefix[at]) as usize);
                        let new_slot = usize::from(cold_units.len() >= free_ranges) * std::mem::size_of::<ColdUnit>();
                        let overhead = new_slot + std::mem::size_of::<SpanMembers>() + 32 + 4 * members.capacity();
                        if saved <= overhead {
                            allocations.removing = false;
                            allocations.items(items);
                            allocations.removing = true;
                            continue;
                        }
                        let end_row = Self::end_row(scene, unit, items);
                        let range_info = ColdUnit::new(ui, logical as usize, unit, end_row)?;
                        cold_units.push((range_info, SpanMembers { draw: draw_key(&mut self.identities, items), members }));
                        bytes -= saved - overhead;
                        cold_owner[range.clone()].fill(ui);
                        evict[range].fill(true);
                    }
                }
            }
        }
        if bytes > budget { return None; }
        // The owner may decline an optional recording and retain this plan. Commit
        // cold-unit ownership only when its replacement slot map can also be published.
        self.units.add(cold_units);
        let kept = evict.iter().filter(|&&cold| !cold).count();
        let mut items = Vec::with_capacity(kept);
        let mut slots = Vec::with_capacity(kept);
        let mut offsets = Vec::with_capacity(plan.items.len() + 1);
        for (at, (item, cold)) in plan.items.iter().zip(evict).enumerate() {
            offsets.push(items.len());
            if !cold {
                slots.push(if first { at as u32 } else { self.addresses.slots[at] });
                items.push(item.clone());
            }
        }
        offsets.push(items.len());
        if let Some(seg) = seg {
            for (ui, unit) in seg.units.iter_mut().enumerate() {
                unit.item_start = if self.units.get(ui).is_some() { ABSENT } else { offsets[seg.prefix + unit.item_start] };
            }
            seg.prefix = 0;
            seg.item_len = kept;
        }
        index.spans.remap_starts(|si, start, len| {
            if start >= IN_UNIT { return start; }
            if absent[si] { return ABSENT; }
            if let Some(cold) = cold_owner.get(start).and_then(|ui| self.units.spans.get_mut(ui)) {
                if len != 0 {
                    cold.members.push(si as u32);
                    return IN_UNIT;
                }
            }
            offsets[start]
        });
        let sorted = slots.windows(2).position(|pair| pair[1] <= pair[0]).map_or(slots.len(), |i| i + 1);
        let suffix: HashMap<_, _> = slots[sorted..].iter().copied().zip(sorted as u32..).collect();
        self.identities.geometry.retain(|_, (key, _)| key.strong_count() != 0);
        self.identities.pixels.retain(|_, (key, _)| key.strong_count() != 0);
        bytes = bytes.saturating_sub(previous_overhead) + self.identities.bytes();
        bytes += suffix.capacity() * std::mem::size_of::<(u32, u32)>();
        self.addresses = Arc::new(ItemAddresses { total: self.addresses.total, sorted, suffix, slots });
        Some((plan.with_items(items), bytes))
    }

    /// A contiguous rewrite can retain the prefix and suffix of the physical
    /// list when they already occupy their complete logical ranges.
    pub(super) fn rewrite_range(&self, sources: &[usize]) -> Option<std::ops::Range<usize>> {
        if self.units.ranges.iter().any(|r| r.len != 0) { return None; }
        let start = self.start(*sources.first()?);
        let mut end = start;
        for &si in sources {
            let span = self.spans.get(si)?;
            if span.logical as usize != end { return None; }
            end += span.len as usize;
        }
        let slots = &self.addresses.slots;
        let suffix = self.addresses.total.checked_sub(end)?;
        if slots.get(..start)?.iter().copied().ne(0..start as u32)
            || slots.get(slots.len().checked_sub(suffix)?..)?.iter().copied().ne(end as u32..self.addresses.total as u32) {
            return None;
        }
        Some(start..end)
    }

    /// Open the missing logical slots in place. Restored rows after the sorted
    /// prefix can be out of order, so save those until the prefix is in place.
    pub(super) fn expand_rewrite(&self, items: &mut Vec<DrawItem>) {
        let addresses = &self.addresses;
        if addresses.complete() { return; }
        let restored = items.split_off(addresses.sorted);
        items.resize_with(addresses.total, || DrawItem::Vacant);
        for (at, &logical) in addresses.slots[..addresses.sorted].iter().enumerate().rev() {
            items.swap(at, logical as usize);
        }
        for (&logical, item) in addresses.slots[addresses.sorted..].iter().zip(restored) {
            items[logical as usize] = item;
        }
    }

    pub(super) fn finish_rewrite(&mut self) {
        let total = self.addresses.total;
        self.addresses = Arc::new(ItemAddresses { total, sorted: total, slots: (0..total as u32).collect(), suffix: Default::default() });
    }

    pub(super) fn restore(&mut self, si: usize, span: &mut NodeSpan, plan: &mut CoveragePlan,
        items: Vec<DrawItem>, written: &mut PlanWritten, geometry_stands: bool) -> Option<()> {
        let source = self.spans.get(si)?;
        if items.len() != span.len || items.len() != source.len as usize { return None; }
        if !geometry_stands && draw_key(&mut self.identities, &items) != Some(source.draw) { written.recollect = true; }
        span.start = plan.items.len();
        let end = span.start.checked_add(span.len)?;
        u32::try_from(end).ok()?;
        written.placed.extend((span.start..end).map(crate::frame::ItemWrite::full));
        Arc::make_mut(&mut self.addresses).append(source.logical, source.len)?;
        plan.items.extend(items);
        Some(())
    }

    pub(super) fn opacity_write(&self, ui: usize, row: u32, opacity: f32) -> Option<crate::frame::LogicalWrite> {
        let unit = self.units.get(ui)?;
        (unit.end_row == row).then(|| crate::frame::LogicalWrite { logical: unit.logical as usize + unit.len as usize - 1,
            value: crate::frame::LogicalValue::CompositeOpacity(opacity) })
    }

    pub(super) fn opacity_source(&self, ui: usize) -> Option<(crate::frame::PlanUnit, u32)> {
        let unit = self.units.get(ui)?;
        (unit.end_row != u32::MAX).then(|| (unit.source(), unit.end_row))
    }

    pub(super) fn restore_unit(&mut self, ui: usize, index: &mut PlanIndex, plan: &mut CoveragePlan,
        items: Vec<DrawItem>, written: &mut PlanWritten) -> Option<(usize, i64)> {
        let pos = self.units.position(ui)?;
        let cold = self.units.ranges[pos];
        let spans = self.units.spans.remove(&ui);
        // With flat spans the full header takes ownership again. Otherwise this
        // compact range remains the source for the next eviction and CPU read.
        if spans.is_some() { self.units.ranges[pos].len = 0; }
        let at = plan.items.len();
        let draw = spans.as_ref().and_then(|s| s.draw);
        if draw.is_none() || draw_key(&mut self.identities, &items) != draw { written.recollect = true; }
        let count = u32::try_from(items.len()).ok()?;
        let end = u32::try_from(at).ok()?.checked_add(count)?;
        written.placed.extend((at..end as usize).map(crate::frame::ItemWrite::full));
        Arc::make_mut(&mut self.addresses).append(cold.logical, count)?;
        for &si in spans.iter().flat_map(|s| &s.members) {
            let slot = self.spans[si as usize].logical.checked_sub(cold.logical)?;
            index.spans[si as usize].start = at + slot as usize;
        }
        let delta = (items_bytes(&items) + 4 * items.len()) as i64
            - spans.map_or(0, |s| std::mem::size_of::<SpanMembers>() + 32 + weights::capacity(&s.members)) as i64;
        plan.items.extend(items);
        Some((at, delta))
    }

    fn emit_unit(cold: &ColdUnit, units: &Units, masks: &weights::RetainedSet<String>, plan: &CoveragePlan,
        scene: &Scene, opts: &RenderOptions, caches: &mut PlanCaches, hashes: &dyn NodeHashSource,
        owners: &mut Option<HashMap<String, usize>>) -> Option<Vec<DrawItem>> {
        let seg = units.segment.as_ref()?;
        let source = cold.source();
        let unit = seg.units.get(cold.index as usize).unwrap_or(&source);
        let dl = units.sources.load(&seg.dl, scene, unit, masks)?;
        let mut build = crate::frame::rebuild_page_range(scene, plan, seg, &dl, opts, Some((caches, hashes)),
            unit.z, None, &[], false, None)?;
        validate_unit_output(&mut build, unit, true, true, &plan.masks, owners, None)?;
        Some(build.items)
    }

    pub(super) fn materialize_units(&self, patch: &Patchable, plan: &CoveragePlan, scene: &Scene,
        opts: &RenderOptions, caches: &mut PlanCaches, hashes: &dyn NodeHashSource, dest: &mut [DrawItem]) -> Option<()> {
        let mut owners = None;
        for cold in self.units.ranges.iter().filter(|u| u.len != 0) {
            let at = cold.logical as usize;
            if !matches!(dest.get(at)?, DrawItem::Vacant) { continue; }
            let out = Self::emit_unit(cold, patch.units.as_ref()?, &patch.index.deps.mask_source_ids, plan, scene, opts, caches, hashes, &mut owners)?;
            for (slot, item) in dest.get_mut(at..at + out.len())?.iter_mut().zip(out) { *slot = item; }
        }
        Some(())
    }

    /// Bring back only the cold draw ranges that read a publication. The normal pattern
    /// writer then works against the same ordinary paint items as it does on a dense plan.
    #[allow(clippy::too_many_arguments)]
    pub(super) fn restore_inputs(&mut self, missing: &[usize], patch: &mut Patchable, plan: &mut CoveragePlan,
        scene: &Scene, opts: &RenderOptions, caches: &mut PlanCaches, hashes: &dyn NodeHashSource, written: &mut PlanWritten) -> Option<i64> {
        let includes = |start: usize, len: usize| {
            let i = missing.partition_point(|&at| at < start);
            missing.get(i).is_some_and(|&at| at < start + len)
        };
        let mut owners = None;
        let index = &mut patch.index;
        let mut delta = 0;
        if let Some(units) = &mut patch.units {
            let cold: Vec<_> = self.units.ranges.iter().copied().filter(|u| u.len != 0 && includes(u.logical as usize, u.len as usize)).collect();
            for cold in cold {
                let ui = cold.index as usize;
                let items = Self::emit_unit(&cold, units, &index.deps.mask_source_ids, plan, scene, opts, caches, hashes, &mut owners)?;
                let (at, size) = self.restore_unit(ui, index, plan, items, written)?;
                let seg = units.segment.as_mut()?;
                if let Some(unit) = seg.units.get_mut(ui) { unit.item_start = at.checked_sub(seg.prefix)?; }
                delta += size;
            }
        }
        let seg = patch.units.as_ref().and_then(|u| u.segment.as_ref());
        let (backdrop, layer) = seg.map_or((None, None), |s| crate::frame::page_range_contexts(scene, plan, s, opts));
        // Scan the compact logical ranges without expanding unrelated span pages.
        for si in 0..self.spans.len() {
            let range = self.spans[si];
            if !includes(range.logical as usize, range.len as usize) || index.spans[si].start != ABSENT { continue; }
            let span = &mut index.spans[si];
            let (out, consumed, recipe) = emit_span(scene, span, opts, index.transparent, index.page_clip, backdrop.as_ref(), layer.as_ref(),
                caches, hashes, &plan.masks, &index.deps.mask_source_ids, true, seg, &mut owners)?;
            if consumed != span.z_consumed { return None; }
            delta += (items_bytes(&out) + 4 * out.len()) as i64;
            self.restore(si, span, plan, out, written, false)?;
            span.placement = recipe;
        }
        Some(delta)
    }

    #[cfg(test)]
    pub(super) fn has_cold_units(&self) -> bool { self.units.ranges.iter().any(|r| r.len != 0) }

    pub(super) fn span_range(&self, si: usize) -> std::ops::Range<usize> {
        let span = self.spans[si];
        span.logical as usize..span.logical as usize + span.len as usize
    }

    pub(super) fn start(&self, si: usize) -> usize { self.spans[si].logical as usize }
}
